entries[10604] = { ["name"] = "Bauplan: Schwerkalibriges Mithrilgewehr", ["text"] = "Benötigt Ingenieurskunst (220)\nBenutzen: Lehrt Euch die Herstellung eines schwerkalibrigen Mithrilgewehrs.\nVerkaufspreis:\nSchwerkalibriges Mithrilgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n68 - 127 Schaden Tempo 2.90\n(33.62 Schaden pro Sekunde)\n+ 42 Distanzangriffskraft\nHaltbarkeit 85 / 85\nBenötigt Stufe 39\nVerkaufspreis:\nBenötigt Mithrilrohr (2), Instabiler Auslöser , Schwerer Griff , Mithrilbarren (6), Citrin (2)" }
entries[10605] = { ["name"] = "Bauplan: Zaubermachtschutzbrille Xtrem", ["text"] = "Benötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch die Herstellung einer Zaubermachtschutzbrille Xtrem.\nVerkaufspreis:\nZaubermachtschutzbrille Xtrem\nWird beim Anlegen gebunden\nKopf Stoff\n90 Rüstung\n+18 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst (215)\nVerkaufspreis:\nBenötigt Dickes Leder (4), Sternrubin (2)" }
entries[10606] = { ["name"] = "Bauplan: Fallschirmumhang", ["text"] = "Benötigt Ingenieurskunst (225)\nBenutzen: Lehrt Euch die Herstellung eines Fallschirmumhangs.\nVerkaufspreis:\nFallschirmumhang\nWird beim Anlegen gebunden\nRücken\n58 Rüstung\n+8 Beweglichkeit\nBenötigt Ingenieurskunst (225)\nBenutzen: Reduziert 10 Sek. lang Euer Falltempo. (30 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Magiestoffballen (4), Schattenseide (2), Instabiler Auslöser , Robustes Sprengpulver (4)" }
entries[10607] = { ["name"] = "Bauplan: Tiefseetaucherhelm", ["text"] = "Benötigt Ingenieurskunst (230)\nBenutzen: Lehrt Euch die Herstellung eines Tiefseetaucherhelms.\nVerkaufspreis:\nTiefseetaucherhelm\nWird beim Anlegen gebunden\nKopf Stoff\n96 Rüstung\n+15 Ausdauer\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst (230)\nAnlegen: Ermöglicht Unterwasseratmung.\nVerkaufspreis:\nBenötigt Mithrilbarren (8), Mithrilgehäuse , Echtsilberbarren , Tigerauge (4), Malachit (4)" }
