entries[10721] = { ["name"] = "Gnomenunglücksverhinderungsgürtel", ["text"] = "Wird beim Anlegen gebunden\nTaille Leder\n95 Rüstung\n+6 Ausdauer\nHaltbarkeit 40 / 40\nBenötigt Ingenieurskunst (215)\nBenutzen: Ein Kraftfeldschild schützt Euch 10 Min. lang vor bis zu 667 Schaden.\nWARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)\nVerkaufspreis:" }
